interface DroneController { String flyTo(String waypoint); }
class DjiController implements DroneController {
    public String flyTo(String waypoint) { return "flying:" + waypoint; }
}
public class RealWorldAbstractionDemo {
    static String mission(DroneController controller) { return controller.flyTo("WP-7"); }
    public static void main(String[] args) { System.out.println(mission(new DjiController())); }
}
